package dev.pixel.sync;

import android.app.*;
import android.appwidget.*;
import android.content.*;
import android.content.res.Configuration;
import android.graphics.*;
import android.os.Bundle;
import android.view.View;
import android.widget.RemoteViews;
import org.json.*;
import java.time.*;

public class CalendarWidget extends AppWidgetProvider {
    public static class Agenda extends CalendarWidget {}
    public static class Countdown extends CalendarWidget {}
    static android.content.SharedPreferences prefs(Context c,int id){return c.getSharedPreferences("calendar_widget_"+id,0);}
    static String mode(Context c,int id){AppWidgetProviderInfo i=AppWidgetManager.getInstance(c).getAppWidgetInfo(id);return i!=null&&i.provider.getClassName().endsWith("$Agenda")?"agenda":i!=null&&i.provider.getClassName().endsWith("$Countdown")?"countdown":"calendar";}
    static void updateAll(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);for(Class<?> cls:new Class<?>[]{CalendarWidget.class,Agenda.class,Countdown.class})for(int id:m.getAppWidgetIds(new ComponentName(c,cls)))update(c,id);}
    public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)update(c,id);CalendarUpdates.changed(c);}
    public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,Bundle options){update(c,id);}
    public void onDeleted(Context c,int[] ids){for(int id:ids)prefs(c,id).edit().clear().apply();}
    public void onReceive(Context c,Intent intent){super.onReceive(c,intent);if(!"dev.pixel.sync.CALENDAR_WIDGET".equals(intent.getAction()))return;int id=intent.getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,-1);if(AppWidgetManager.getInstance(c).getAppWidgetInfo(id)==null)return;synchronized(CalendarWidgetActions.class){android.content.SharedPreferences p=prefs(c,id);String action=intent.getStringExtra("action");if("cycle".equals(action))p.edit().putBoolean("cycle",!p.getBoolean("cycle",false)).putInt("revision",p.getInt("revision",0)+1).apply();else if("prev".equals(action)||"next".equals(action)){int value=p.getInt("offset",0)+("prev".equals(action)?-1:1);p.edit().putInt("offset",Math.max(-120,Math.min(120,value))).putInt("revision",p.getInt("revision",0)+1).apply();}}update(c,id);}
    private static PendingIntent action(Context c,int id,String action){AppWidgetProviderInfo info=AppWidgetManager.getInstance(c).getAppWidgetInfo(id);Intent i=new Intent("dev.pixel.sync.CALENDAR_WIDGET").setComponent(info.provider).setData(android.net.Uri.parse("greta-calendar://widget/"+id+"/"+action)).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id).putExtra("action",action);return PendingIntent.getBroadcast(c,id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    private static PendingIntent open(Context c,int id,String date,String item,boolean add){Intent i=new Intent(c,CalendarActivity.class).setData(android.net.Uri.parse("greta-calendar://open/"+id+"/"+date+"/"+item+"/"+add)).putExtra("date",date).putExtra("item",item).putExtra("add",add);return PendingIntent.getActivity(c,id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    static void update(Context c,int id){
        try(CalendarStore store=new CalendarStore(c)){
            android.content.SharedPreferences p=prefs(c,id);int theme=p.getInt("theme",c.getSharedPreferences("home",0).getInt("theme",0));boolean dark=theme==2||(theme==0&&(c.getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES);boolean show=p.getBoolean("cycle",false);String mode=mode(c,id);JSONObject prediction=store.prediction();int ink=dark?0xFFE7F0EC:0xFF243F37,muted=dark?0xFFA8BDB8:0xFF61776F;
            YearMonth month=YearMonth.now().plusMonths(p.getInt("offset",0));RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.calendar_widget);v.setInt(R.id.calendar_widget_root,"setBackgroundResource",dark?R.drawable.calendar_widget_dark:R.drawable.calendar_widget_light);v.setTextViewText(R.id.widget_month,typography(c,month.getMonthValue()+"月 "+month.getYear()));
            for(int view:new int[]{R.id.widget_month,R.id.widget_prev,R.id.widget_next,R.id.widget_cycle,R.id.widget_add})v.setTextColor(view,ink);v.setTextColor(R.id.widget_summary,muted);
            v.setOnClickPendingIntent(R.id.widget_prev,action(c,id,"prev"));v.setOnClickPendingIntent(R.id.widget_next,action(c,id,"next"));if(!show&&!store.settings().optBoolean("enabled")&&store.cycles().isEmpty()){
                Intent setup=new Intent(c,CalendarActivity.class).setData(android.net.Uri.parse("greta-calendar://cycle-setup/"+id)).putExtra("cycle_setup",true);
                v.setOnClickPendingIntent(R.id.widget_cycle,PendingIntent.getActivity(c,id,setup,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));
            }else v.setOnClickPendingIntent(R.id.widget_cycle,action(c,id,"cycle"));v.setTextColor(R.id.widget_cycle,show?(dark?0xFFB7DAC5:0xFF38694F):muted);v.setOnClickPendingIntent(R.id.widget_add,open(c,id,LocalDate.now().toString(),"",true));v.setOnClickPendingIntent(R.id.widget_month,open(c,id,month.atDay(1).toString(),"",false));
            v.setViewVisibility(R.id.widget_header,"countdown".equals(mode)?View.GONE:View.VISIBLE);v.setViewVisibility(R.id.widget_summary,"calendar".equals(mode)?View.VISIBLE:View.GONE);v.setInt(R.id.calendar_widget_root,"setGravity","countdown".equals(mode)?android.view.Gravity.CENTER_VERTICAL:android.view.Gravity.TOP);
            v.setViewVisibility(R.id.widget_calendar_frame,"calendar".equals(mode)?View.VISIBLE:View.GONE);v.setViewVisibility(R.id.widget_prev,"calendar".equals(mode)?View.VISIBLE:View.GONE);v.setViewVisibility(R.id.widget_next,"calendar".equals(mode)?View.VISIBLE:View.GONE);
            if("calendar".equals(mode)){
                CalendarMonthView grid=new CalendarMonthView(c);grid.forWidget();grid.bind(month,LocalDate.now(),dark,show,store,null);int rows=(month.atDay(1).getDayOfWeek().getValue()-1+month.lengthOfMonth()+6)/7;int width=Math.max(200,Math.min(700,AppWidgetManager.getInstance(c).getAppWidgetOptions(id).getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,350)-28));int gridHeight=24+rows*44;v.setViewLayoutHeight(R.id.widget_calendar_frame,gridHeight,android.util.TypedValue.COMPLEX_UNIT_DIP);Bitmap bitmap=Bitmap.createBitmap(width,gridHeight,Bitmap.Config.ARGB_8888);grid.drawMonth(new Canvas(bitmap),bitmap.getWidth(),bitmap.getHeight());v.setImageViewBitmap(R.id.widget_calendar_image,bitmap);
                v.removeAllViews(R.id.widget_calendar_hits);LocalDate first=month.atDay(1).minusDays(month.atDay(1).getDayOfWeek().getValue()-1);
                for(int row=0;row<rows;row++){RemoteViews week=new RemoteViews(c.getPackageName(),R.layout.calendar_widget_row);for(int col=0;col<7;col++){LocalDate d=first.plusDays(row*7+col);RemoteViews day=new RemoteViews(c.getPackageName(),R.layout.calendar_widget_day);day.setContentDescription(R.id.widget_day,d+"，农历"+CalendarDates.lunar(d).label());day.setOnClickPendingIntent(R.id.widget_day,open(c,id,d.toString(),"",false));week.addView(R.id.widget_week,day);}v.addView(R.id.widget_calendar_hits,week);}
            }
            v.removeAllViews(R.id.widget_events);JSONArray events=store.events(LocalDate.now(),LocalDate.now().plusYears(1));int count=0;
            if("countdown".equals(mode)){
                String chosen=p.getString("event","");JSONObject item=chosen.isEmpty()?null:store.get(chosen);if(item!=null&&!item.optBoolean("deleted")){LocalDate d=CalendarDates.occurrence(item,LocalDate.now());if(d!=null){String title=item.getString("title");long days=CalendarDates.days(LocalDate.now(),d);long value=item.optBoolean("count_up")?CalendarDates.days(LocalDate.parse(item.getString("date")),LocalDate.now()):days;String label=item.optBoolean("count_up")?(value<0?"天后开始":"已经"):(value<0?"已过":"天后");String display=value==0&&!item.optBoolean("count_up")?"今天":String.valueOf(Math.abs(value));widgetEvent(c,v,id,item,display+"\n"+title+(display.equals("今天")?"":" · "+label),ink,d);count++;}}
                v.setViewVisibility(R.id.widget_cycle,View.GONE);
            }else{int height=AppWidgetManager.getInstance(c).getAppWidgetOptions(id).getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,"calendar".equals(mode)?480:180);int rows=(month.atDay(1).getDayOfWeek().getValue()-1+month.lengthOfMonth()+6)/7;int limit="agenda".equals(mode)?Math.max(1,Math.min(3,(height-70)/55)):Math.max(0,Math.min(3,(height-94-(24+rows*44))/60));if("agenda".equals(mode)&&show&&prediction.optBoolean("available")&&limit>0){LocalDate due=LocalDate.parse(prediction.getString("next_start"));long days=CalendarDates.days(LocalDate.now(),due);RemoteViews period=new RemoteViews(c.getPackageName(),R.layout.calendar_widget_event);period.setTextViewText(R.id.widget_event,typography(c,"大姨妈 · "+(days<0?"尚未记录本次开始":"预计"+days+"天后")+"\n仅为日期估算，供记录参考"));period.setTextColor(R.id.widget_event,ink);period.setOnClickPendingIntent(R.id.widget_event,open(c,id,due.toString(),"",false));v.addView(R.id.widget_events,period);count++;limit--;}
                for(int n=0;n<Math.min(events.length(),limit);n++){JSONObject e=events.getJSONObject(n);long days=e.getLong("days_until");widgetEvent(c,v,id,e,e.getString("title")+"  ·  "+(days==0?"就是今天":days+"天后")+"\n"+e.getString("occurrence"),ink,LocalDate.parse(e.getString("occurrence")));count++;}}
            if(count==0&&(!"calendar".equals(mode)||events.length()==0)){RemoteViews row=new RemoteViews(c.getPackageName(),R.layout.calendar_widget_event);row.setTextViewText(R.id.widget_event,"countdown".equals(mode)?"长按组件，选择要展示的纪念日":"添加一个值得记住的日子");row.setTextColor(R.id.widget_event,muted);row.setOnClickPendingIntent(R.id.widget_event,open(c,id,LocalDate.now().toString(),"",true));v.addView(R.id.widget_events,row);}
            String summary="Greta · 农历"+CalendarDates.lunar(LocalDate.now()).label();if(show&&prediction.optBoolean("available")){long days=CalendarDates.days(LocalDate.now(),LocalDate.parse(prediction.getString("next_start")));summary=days<0?"大姨妈预计日期已过 · 尚未记录本次开始":"大姨妈预计 "+days+" 天后 · 仅供参考";}v.setTextViewText(R.id.widget_summary,typography(c,summary));AppWidgetManager.getInstance(c).updateAppWidget(id,v);
        }catch(Exception error){android.util.Log.w("GretaCalendar","Widget update failed: "+error.getClass().getSimpleName());}
    }
    private static CharSequence typography(Context c,CharSequence text){if(c.getSharedPreferences("home",0).getInt("font",0)!=1)return text;android.text.SpannableString value=new android.text.SpannableString(text);value.setSpan(new android.text.style.TypefaceSpan("serif"),0,value.length(),0);return value;}
    private static void widgetEvent(Context c,RemoteViews root,int id,JSONObject e,String text,int ink,LocalDate date){RemoteViews row=new RemoteViews(c.getPackageName(),R.layout.calendar_widget_event);CharSequence styled=text;if("countdown".equals(mode(c,id))){android.text.SpannableString span=new android.text.SpannableString(text);int split=text.indexOf('\n');if(split>0){span.setSpan(new android.text.style.AbsoluteSizeSpan(40,true),0,split,0);span.setSpan(new android.text.style.AbsoluteSizeSpan(14,true),split,text.length(),0);}styled=span;row.setInt(R.id.widget_event,"setGravity",android.view.Gravity.CENTER);}row.setTextViewText(R.id.widget_event,typography(c,styled));row.setTextColor(R.id.widget_event,ink);row.setOnClickPendingIntent(R.id.widget_event,open(c,id,date.toString(),e.optString("id"),false));root.addView(R.id.widget_events,row);}
}
